activities.codeSnippet:
public class Main {
    public static void main(String[] args) {
        // Without loops: 5 lines of repetitive code
        // With a loop: 3 clean lines of code
        int customerNumber = 1; // 1. Initialization

        while (customerNumber <= 5) { // 2. Condition
            System.out.println("Serving Customer Ticket #" + customerNumber); // 3. Body
            customerNumber++; // 4. Update
        }

        System.out.println("All 5 customer tickets served!");
    }
}

