practice.solutionCode:
public class Main {
    public static void main(String[] args) {
        int batch = 1;
        while (batch <= 4) {
            System.out.println("Batch #" + batch + ": Welcome to Java Basics");
            batch++;
        }
        System.out.println("All batches welcomed successfully!");
    }
}

