public class Main {
    public static void main(String[] args) {
        int t = 5;
        while (t >= 1) {
            System.out.println(t);
            t--;
        }
        System.out.println("Liftoff!");
    }
}

public class Main {
    public static void main(String[] args) {
        int val = 1;
        int count = 1;
        while (count <= 5) {
            System.out.println(val);
            val *= 2;
            count++;
        }
    }
}

