}

public class Main {
    public static void main(String[] args) {
        int battery = 20;
        while (battery >= 5) {
            System.out.println("Battery at: " + battery + "%");
            battery -= 5;
        }
        System.out.println("Warning: Connect charger immediately!");
    }
}

